CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    CREATE ROLE anon NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    CREATE ROLE authenticated NOLOGIN;
  END IF;
END
$$;

CREATE SCHEMA IF NOT EXISTS auth;
CREATE OR REPLACE FUNCTION auth.uid()
RETURNS uuid
LANGUAGE sql
STABLE
AS $$
  SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
GRANT USAGE ON SCHEMA auth TO anon, authenticated;
GRANT EXECUTE ON FUNCTION auth.uid() TO anon, authenticated;
GRANT USAGE ON SCHEMA public TO anon, authenticated;

CREATE TABLE public.commercial_organizations (
  id uuid PRIMARY KEY
);

CREATE TABLE public.commercial_organization_locations (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id)
);

CREATE TABLE public.commercial_activities (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id)
);

CREATE TABLE public.commercial_organization_members (
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id),
  user_id uuid NOT NULL,
  role text NOT NULL,
  state text NOT NULL,
  PRIMARY KEY (organization_id, user_id)
);

CREATE TABLE public.commercial_warehouses (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id),
  branch_location_id uuid NOT NULL REFERENCES public.commercial_organization_locations(id),
  state text NOT NULL
);

CREATE TABLE public.commercial_storage_locations (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id),
  warehouse_id uuid NOT NULL REFERENCES public.commercial_warehouses(id),
  state text NOT NULL,
  location_type text NOT NULL
);

CREATE TABLE public.commercial_offerings (
  id uuid PRIMARY KEY,
  activity_id uuid NOT NULL REFERENCES public.commercial_activities(id),
  location_ref text NOT NULL
);

CREATE TABLE public.commercial_inventory_balances (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id),
  location_id uuid NOT NULL REFERENCES public.commercial_organization_locations(id),
  offering_id uuid NOT NULL REFERENCES public.commercial_offerings(id),
  quantity_on_hand numeric(20,6) NOT NULL,
  quantity_reserved numeric(20,6) NOT NULL DEFAULT 0,
  UNIQUE (organization_id, location_id, offering_id)
);

CREATE TABLE auth.users (
  id uuid PRIMARY KEY
);

CREATE TABLE public.commercial_audit_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id uuid,
  actor_user_id uuid,
  action text NOT NULL,
  entity_type text NOT NULL,
  entity_id text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.commercial_organization_members,
  public.commercial_inventory_balances TO authenticated;
